// Format filters for the static pages generated by scripts/build-site.mjs:
// a movie's page (theatres showing it) and the movies/ index. Without this
// script both list everything. With it, picking formats narrows the list to
// entries in any of them, and carries the selection into the URL and into
// each link (movie and theatre pages read the same "formats" param).
const filterEl = document.getElementById("movie-filter");
const countEl = document.getElementById("movie-count");

// The province a visitor last opened on a movie page, reopened on the next
// one. A per-browser convenience, so storage failures are ignored.
const PROVINCE_KEY = "cinescan:province";

function readStoredProvince() {
  try {
    return localStorage.getItem(PROVINCE_KEY);
  } catch {
    return null;
  }
}

function storeProvince(province) {
  try {
    if (province) localStorage.setItem(PROVINCE_KEY, province);
    else localStorage.removeItem(PROVINCE_KEY);
  } catch {
    // Private mode or blocked storage: the page still works, just forgets.
  }
}

// Sets the "formats" param on a URL, or removes it for an empty selection.
function withFormats(href, selected) {
  const url = new URL(href, document.baseURI);
  if (selected.size) url.searchParams.set("formats", [...selected].join(","));
  else url.searchParams.delete("formats");
  return url;
}

// What the collapsed filter's toggle says is selected: "All formats", or
// the first couple of tags, e.g. "IMAX, 4DX +1".
function selectionSummary(selected) {
  if (selected.size === 0) return "All formats";
  const tags = [...selected];
  return tags.length > 2 ? `${tags.slice(0, 2).join(", ")} +${tags.length - 2}` : tags.join(", ");
}

// Wires up the chips and calls onChange(selected) with the selected tags
// (empty means everything) on load and after every change.
function setupFormatFilter(onChange) {
  const chips = [...filterEl.querySelectorAll(".format-chip")];
  const allBtn = filterEl.querySelector(".format-clear-btn");
  const knownTags = new Set(chips.map((chip) => chip.dataset.tag));
  const urlFormats = new URLSearchParams(location.search).get("formats");
  let selected = new Set((urlFormats || "").split(",").filter((tag) => knownTags.has(tag)));

  // Only a long filter has a toggle (see COLLAPSE_FILTER_MIN_FORMATS in
  // build-site.mjs); on phones it hides the chips until opened.
  const toggle = document.getElementById("movie-filter-toggle");
  const stateEl = toggle?.querySelector(".filter-toggle-state");

  function apply() {
    for (const chip of chips) {
      const on = selected.has(chip.dataset.tag);
      chip.classList.toggle("active", on);
      chip.setAttribute("aria-pressed", String(on));
    }
    allBtn.classList.toggle("active", selected.size === 0);
    allBtn.setAttribute("aria-pressed", String(selected.size === 0));
    if (stateEl) stateEl.textContent = selectionSummary(selected);
    history.replaceState(history.state, "", withFormats(location.href, selected));
    onChange(selected);
  }

  for (const chip of chips) {
    chip.addEventListener("click", () => {
      const tag = chip.dataset.tag;
      if (selected.has(tag)) selected.delete(tag);
      else selected.add(tag);
      apply();
    });
  }
  allBtn.addEventListener("click", () => {
    selected = new Set();
    apply();
  });

  if (toggle) {
    const wrap = filterEl.closest(".movie-filter-wrap");
    toggle.hidden = false;
    toggle.addEventListener("click", () => {
      toggle.setAttribute("aria-expanded", String(wrap.classList.toggle("open")));
    });
  }

  filterEl.hidden = false;
  apply();
}

function plural(n, word) {
  return `${n} ${word}${n === 1 ? "" : "s"}`;
}

function setupMoviePage() {
  const theatreEls = [...document.querySelectorAll(".movie-theatre")];
  const provinceEls = [...document.querySelectorAll(".movie-province")];

  const stored = readStoredProvince();
  const storedEl = provinceEls.find((el) => el.dataset.province === stored);
  if (storedEl) storedEl.open = true;
  // Only a visitor's own clicks (keyboard activation fires "click" too) are
  // remembered, not "toggle": that also fires for sections opened here or
  // by the build, which would overwrite the visitor's choice.
  for (const provinceEl of provinceEls) {
    provinceEl.querySelector("summary").addEventListener("click", () => {
      const opening = !provinceEl.open; // the click's default action toggles it afterwards
      if (opening) storeProvince(provinceEl.dataset.province);
      else if (readStoredProvince() === provinceEl.dataset.province) storeProvince(null);
    });
  }

  setupFormatFilter((selected) => {
    let shown = 0;
    for (const theatreEl of theatreEls) {
      let any = false;
      for (const comboEl of theatreEl.querySelectorAll("[data-formats]")) {
        const visible =
          selected.size === 0 || comboEl.dataset.formats.split("|").some((t) => selected.has(t));
        comboEl.hidden = !visible;
        any ||= visible;
      }
      theatreEl.hidden = !any;
      if (any) shown++;

      const link = theatreEl.querySelector("[data-theatre-link]");
      link.href = withFormats(link.getAttribute("href"), selected);
    }

    const visibleProvinces = [];
    for (const provinceEl of provinceEls) {
      const all = provinceEl.querySelectorAll(".movie-theatre").length;
      const visible = provinceEl.querySelectorAll(".movie-theatre:not([hidden])").length;
      provinceEl.hidden = visible === 0;
      provinceEl.querySelector(".movie-province-count").textContent = selected.size
        ? `${visible} of ${plural(all, "theatre")}`
        : plural(all, "theatre");
      if (visible) visibleProvinces.push(provinceEl);
    }
    // Nothing left to choose between, so save the extra click.
    if (visibleProvinces.length === 1) visibleProvinces[0].open = true;

    countEl.textContent = selected.size
      ? `Showing ${shown} of ${plural(theatreEls.length, "theatre")}`
      : plural(theatreEls.length, "theatre");
  });
}

function setupMovieIndex() {
  const cardEls = [...document.querySelectorAll(".movie-grid > li")];
  const sectionEls = [...document.querySelectorAll(".movie-index-section")];

  setupFormatFilter((selected) => {
    let shown = 0;
    for (const cardEl of cardEls) {
      const counts = JSON.parse(cardEl.dataset.counts);
      const matching = [...selected].filter((tag) => counts[tag]);
      const visible = selected.size === 0 || matching.length > 0;
      cardEl.hidden = !visible;
      if (visible) shown++;

      const link = cardEl.querySelector(".movie-card");
      link.href = withFormats(link.getAttribute("href"), selected);
      for (const badge of cardEl.querySelectorAll(".format-badge[data-extra]")) {
        badge.hidden = !selected.has(badge.dataset.tag);
      }

      // e.g. "12 theatres in IMAX · 3 in 4DX" instead of the overall count.
      const metaEl = cardEl.querySelector(".movie-card-meta");
      metaEl.dataset.all ??= metaEl.textContent;
      const byFormat = matching.map(
        (tag, i) => `${i === 0 ? plural(counts[tag], "theatre") : counts[tag]} in ${tag}`
      );
      metaEl.textContent = selected.size
        ? [cardEl.dataset.opens, ...byFormat].filter(Boolean).join(" · ")
        : metaEl.dataset.all;
    }
    for (const sectionEl of sectionEls) {
      sectionEl.hidden = !sectionEl.querySelector(".movie-grid > li:not([hidden])");
    }
    countEl.textContent = selected.size
      ? `Showing ${shown} of ${plural(cardEls.length, "movie")}`
      : plural(cardEls.length, "movie");
  });
}

if (filterEl) {
  if (document.querySelector(".movie-province")) setupMoviePage();
  else if (document.querySelector(".movie-grid")) setupMovieIndex();
}
